const email = $input.first().json || {};
const extractAddress = (value) => {
  if (!value) return '';
  if (typeof value === 'string') {
    const match = value.match(/<([^>]+)>/);
    return (match ? match[1] : value).trim();
  }
  if (Array.isArray(value.value) && value.value[0]?.address) return String(value.value[0].address).trim();
  if (value.address) return String(value.address).trim();
  return '';
};
const from = extractAddress(email.from);
const subject = String(email.subject || '').trim();
const text = String(email.text || email.textPlain || email.html || '').trim();
if (!from) {
  return [{ json: { shouldReply: false, reason: 'missing_from', subject, text } }];
}
return [{ json: { shouldReply: true, toEmail: from, subject: subject ? `Re: ${subject}` : 'Re: test message', body: `Автоответ тестового стенда получен.\n\nOriginal subject: ${subject || '(empty)'}\nOriginal body preview: ${text.slice(0, 500)}` } }];
